const typeIdFrom = (subTypeId: string) => subTypeId.replace(/-st\d+$/, '');
const defaultRole = (difficulty: PhysicsRemediationSeed['difficulty']): PracticeRole =>
  difficulty === 'easy' ? 'guided' : difficulty === 'hard' ? 'mastery_holdout' : 'near_transfer';

export const g10PhysicsModule2RemediationQuestions: Question[] = g10PhysicsModule2RemediationSeeds.map(seed => {
  const role = seed.practiceRole ?? defaultRole(seed.difficulty);
  return {
    id: seed.id,
    subjectId: 'physics',
    topicId: 'phy10-t2',
    questionTypeId: typeIdFrom(seed.subTypeId),
    subTypeId: seed.subTypeId,
    content: seed.content,
    responseType: seed.options ? 'single_choice' : 'short_answer',
    options: seed.options,
    correctAnswer: seed.correctAnswer,
    acceptedAnswers: seed.options ? [seed.correctAnswer, seed.correctAnswer.toLowerCase()] : (seed.acceptedAnswers ?? [seed.correctAnswer]),
    validatorType: seed.options ? 'choice' : 'exact',
    difficulty: seed.difficulty,
    sourceType: 'manual',
    outcomeIds: seed.outcomeIds,
    competency: seed.competency ?? (seed.difficulty === 'hard' ? 'physical_application' : 'physical_cognition'),
    cognitiveLevel: seed.cognitiveLevel ?? (seed.difficulty === 'easy' ? 'recognition' : seed.difficulty === 'hard' ? 'application' : 'understanding'),
    estimatedSeconds: seed.estimatedSeconds ?? (seed.difficulty === 'easy' ? 40 : seed.difficulty === 'hard' ? 85 : 60),
    practiceRole: role,
    representationType: seed.representationType ?? (seed.options ? 'text' : 'equation'),
    isMasteryHoldout: role === 'mastery_holdout',
    stimulus: seed.stimulus
  };
});

export const g10PhysicsModule2RemediationSolutions: Solution[] = g10PhysicsModule2RemediationSeeds.map(seed => ({
  id: seed.id.replace('-q', '-s'),
  questionId: seed.id,
  recognition: 'Cô lập vật, chọn trục và xác định đúng lực trước khi lập phương trình.',
  detailedSteps: seed.reasoning.map((explanation, index) => ({
    order: index + 1,
    title: index === 0 ? 'Phân tích' : index === seed.reasoning.length - 1 ? 'Kết luận' : 'Tính toán',
    explanation,
    ...(index === seed.reasoning.length - 1 ? { result: seed.correctAnswer } : {})
  })),
  finalAnswer: seed.correctAnswer,
  commonMistakes: ['Nhầm lực tác dụng lên vật với lực do vật tác dụng lên vật khác, hoặc cộng độ lớn mà bỏ hướng.'],
  reviewSuggestions: ['Vẽ sơ đồ lực tự do và chiếu theo từng trục trước khi thay số.']
}));
